{{-- Host only: the caller supplies the current permission-filtered usage DTO and actions. --}}
<style>
.eusage{display:grid;gap:24px;min-width:0;color:var(--ink,#233d32);overflow-wrap:anywhere}.eusage *{box-sizing:border-box}.eusage h2{font:400 31px/1.2 Georgia,serif;margin:12px 0}.eusage h3{font:600 16px/1.6 system-ui,sans-serif;margin:0 0 9px}.eusage h4,.eusage h5{font:600 13px/1.6 system-ui,sans-serif;margin:0 0 7px}.eusage p{font:12px/1.85 system-ui,sans-serif;color:#52654b;margin:8px 0}.eusage-hero{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(220px,1fr);gap:24px;padding:27px;border:1px solid #d4dfc9;border-radius:10px;background:linear-gradient(120deg,#eaf0e2,#fafcf6)}.eusage-meta{padding:17px;border:1px solid #d0dbc4;background:#ffffffcf;border-radius:7px;align-self:start}.eusage-meta strong{font:600 13px/1.6 system-ui,sans-serif}.eusage-badge{display:inline-flex;min-height:28px;align-items:center;padding:4px 8px;border:1px solid #c5d3b8;border-radius:4px;background:#f1f6e9;color:#3c5b35;font:600 10px/1.5 system-ui,sans-serif;letter-spacing:.04em}.eusage-notice{padding:13px 16px;border-left:3px solid #ab8743;background:#faf5e5;color:#65572e!important}.eusage-metrics,.eusage-money-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.eusage-card{min-width:0;background:white;border:1px solid var(--line,#dce3d3);border-radius:8px;padding:20px}.eusage-value{display:block;font:500 30px/1.5 system-ui,sans-serif;color:#244d3d;margin:8px 0}.eusage-money{display:block;font:500 21px/1.6 system-ui,sans-serif;color:#244d3d;margin:8px 0;overflow-wrap:anywhere}.eusage-facts{display:grid;grid-template-columns:minmax(120px,.85fr) minmax(0,1fr);gap:8px 16px;margin:15px 0;font:12px/1.75 system-ui,sans-serif}.eusage-facts dt{color:#64725c}.eusage-facts dd{margin:0;color:#294b34;min-width:0;overflow-wrap:anywhere}.eusage-departments{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.eusage-department-head{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.eusage-button{min-height:44px;padding:10px 13px;border:1px solid #b7c6a9;border-radius:5px;background:#f7faf2;color:#2d5139;font:600 11px/1.6 system-ui,sans-serif;cursor:pointer}.eusage-button:hover{background:#edf3e4}.eusage-button:disabled{opacity:.6;cursor:wait}.eusage :focus-visible{outline:3px solid #9a7c32;outline-offset:3px}.eusage-purpose-list{display:grid;gap:12px;margin-top:18px}.eusage-purpose{border-top:1px solid #e0e6d7;padding-top:15px}.eusage-purpose .eusage-facts{margin:9px 0}.eusage-empty{border:1px dashed #c6d1b9;border-radius:7px;padding:18px;background:#f9fbf5}.eusage-status{min-height:1.8em}@media(max-width:1200px){.eusage-metrics,.eusage-money-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.eusage-departments{grid-template-columns:1fr}}@media(max-width:900px){.eusage-hero{grid-template-columns:1fr}.eusage-facts{grid-template-columns:minmax(100px,.85fr) minmax(0,1fr)}}@media(max-width:650px){.eusage-metrics,.eusage-money-grid{grid-template-columns:1fr}.eusage-hero{padding:20px}.eusage h2{font-size:28px}.eusage-card{padding:18px}.eusage-facts{grid-template-columns:1fr;gap:4px}.eusage-facts dd{margin-bottom:8px}.eusage-department-head{align-items:flex-start;flex-direction:column}.eusage-button{width:100%;font-size:12px}}
</style>
<section id="enterprise-usage-overview" aria-label="Authorized AI usage overview" data-demo-section="usage-overview" hidden></section>
